function hanoi(n, from, via, to, moves) {
  if (n === 0) {
    return;
  }
  hanoi(n - 1, from, to, via, moves);
  moves.push(from + "->" + to);
  hanoi(n - 1, via, from, to, moves);
}

var moves = [];
hanoi(3, "A", "B", "C", moves);
console.log(moves.join(" "));
